mapper.select:
select * from t_xwyy_original_line_spec where DEL_FLAG = 0
and INSTR(ORIGINAL_LINE_CODE, #{originalLineCode, jdbcType=VARCHAR}) > 0
and INSTR(ORIGINAL_LINE_NAME, #{originalLineName, jdbcType=VARCHAR}) > 0
and ORIGINAL_LINE_CODE = #{queryCode,jdbcType=VARCHAR}
order by CREATE_TIME desc
order by ${orderStr}
